import { scan } from './discovery.mjs';
import { readFile } from 'node:fs/promises';
export async function listData(root) {
  const entries = await scan(root, { recursive: true, withFileTypes: true });
  const files = entries.filter(entry => entry.isFile() && entry.name.endsWith('.json'))
    .map(entry => entry.parentPath + '/' + entry.name).sort();
  const rows = [];
  for (const file of files) rows.push(file + '=' + JSON.parse(await readFile(file, 'utf8')).value);
  return rows;
}

