const fs = require('node:fs');
const path = require('node:path');
module.exports = function (source, destination, done) {
  fs.readdir(source, { recursive: true }, function (error, entries) {
    if (error) return done(error);
    let count = 0;
    try {
      for (const name of entries.sort()) {
        if (!name.endsWith('.tpl')) continue;
        const target = destination + '/' + name.slice(0, -4);
        fs.mkdirSync(path.dirname(target), { recursive: true });
        fs.writeFileSync(target, fs.readFileSync(source + '/' + name, 'utf8').replace('[APP]', 'Franken'));
        count++;
      }
    } catch (failure) { done(failure); return; }
    done(null, count);
  });
};

