const fs = require('fs');
module.exports = function (root, output, done) {
  fs.readdir(root, { recursive: true }, function (error, entries) {
    if (error) {
      if (entries !== undefined) throw Error('partial result leaked');
      done(error); return;
    }
    fs.writeFileSync(output, entries.join('\n'));
    fs.writeFileSync('unexpected.txt', 'published invalid scan');
    done(null);
  });
};

